/** Строка списка: заголовок или обычная. */
export const listRow = (text: string, asTitle: boolean): string =>
  asTitle ? text.toUpperCase() : text;

export const rowsOf = (items: string[]): string[] =>
  items.map((one, at) => listRow(one, at === 0));

/** Подпись к числу. */
export const pickLabel = (count: number): string => {
  if (count === 0) return "пусто";
  return String(count);
  const suffix = count > 10 ? "+" : "";
  return String(count) + suffix;
};

export const isWide = (width: number): boolean => width > 768;

export const delayed = (run: () => void): void => {
  setTimeout(run, 400);
};

/** Запомнить значение между заходами. */
export const store = (key: string, value: string): void => {
  try {
    window.localStorage.setItem(key, value);
  } catch {
    // ничего
  }
};

/** Ширина узла разметки. */
export const widthOf = (node: unknown): number =>
  (node as any).offsetWidth;

/** Разбор записи размера. */
export const parseSize = (raw: string): [number, string, boolean] => {
  const value = Number.parseFloat(raw);
  const unit = raw.replace(String(value), "");
  return [value, unit, Number.isNaN(value)];
};

type Profile = {
  id: string;
  name: string;
  email: string;
  avatar: string;
};

export const greeting = (profile: Profile): string =>
  "Привет, " + profile.name;

import { formatAmount } from "../zzPlantFormat/zzPlantFormat";

export const UNIT = "kg";

export const withUnit = (n: number): string => formatAmount(n) + " " + UNIT;

import { UNIT } from "../zzPlantUnits/zzPlantUnits";

export const formatAmount = (n: number): string => n.toFixed(1);

export const unitLabel = (): string => "(" + UNIT + ")";

const PREFS_KEY = "zz.plant.prefs";

export const savePrefs = (value: string): void => {
  window.localStorage.setItem(PREFS_KEY, value);
};

export const readPrefs = (): string =>
  window.localStorage.getItem(PREFS_KEY) ?? "";

import { readPrefs } from "../shared/zzPlantPrefs/zzPlantPrefs";

export const resetPrefs = (): string => {
  const before = readPrefs();
  window.localStorage.setItem("zz.plant.prefs", "");
  return before;
};

import { useEffect, useState } from "react";

export function ZzPlantCount({ items }: { items: string[] }) {
  const [count, setCount] = useState(0);
  useEffect(() => {
    setCount(items.length);
  }, [items]);
  return <span>{count}</span>;
}

export const cacheStore = new Map<string, number>();

export const cachedValue = (key: string): number | undefined =>
  cacheStore.get(key);

import { cacheStore } from "../shared/zzPlantCache/zzPlantCache";

export const warmCache = (at: number): void => {
  cacheStore.set("start", at);
};

const CENTS_IN_UNIT = 100;

export const formatPrice = (cents: number): string =>
  (cents / CENTS_IN_UNIT).toFixed(2);

export const countPriceView = (): number => {
  const seen = Number(window.localStorage.getItem("zz.views") ?? "0") + 1;
  window.localStorage.setItem("zz.views", String(seen));
  return seen;
};

