import { zzProbeRegistry } from "{{from:владелец}}";

export const zzProbeRemember = (name) => {
  zzProbeRegistry.names.push(name);
  zzProbeRegistry.count += 1;
};

export const zzProbeForget = (key) => {
  try {
    window.localStorage.removeItem(key);
  } catch {
    // nothing to do
  }
};

export const zzProbeLabel = (value, compact = false) =>
  compact ? String(value) : "value: " + String(value);

export const zzProbeShortLabel = (value) => zzProbeLabel(value, true);

export const zzProbeParts = (text) => {
  const head = String(text).slice(0, 1);
  const body = String(text).slice(1, -1);
  const tail = String(text).slice(-1);
  return [head, body, tail];
};

let zzProbeCalls = 0;

export const zzProbeNextId = (prefix) => {
  zzProbeCalls += 1;
  return prefix + zzProbeCalls;
};

export const zzProbeAudit = (action, payload) => {
  console.info("[audit]", action, JSON.stringify(payload));
};

export const zzProbeRes = (cfg) => {
  const tmp = cfg.val;
  return tmp;
};
